module Mcp
  # The one way a tool reaches data (generated by maquina:mcp). A token
  # reaches its own user's records, never the whole account, so every tool
  # gets this scope instead of a user and reads through the user's
  # associations:
  #
  #   scope.records(:posts).where(status: "draft")
  #   scope.find(:posts, id)        # someone else's id is the same not found
  #
  # When Mcp.enabled_for?(user) is false (a feature flag that is off), every
  # association comes back empty.
  class UserScope
    attr_reader :user, :oauth_scopes

    def initialize(user, oauth_scopes: [])
      @user = user
      @oauth_scopes = oauth_scopes
    end

    def enabled?
      return @enabled if defined?(@enabled)

      @enabled = Mcp.enabled_for?(user)
    end

    # The user's association by name, or none of it when MCP is off for them.
    def records(association)
      raise ArgumentError, "User has no association #{association.inspect}" unless user.class.reflect_on_association(association)

      relation = user.public_send(association)
      enabled? ? relation : relation.none
    end

    # One of the user's records. A missing id, a malformed id and another
    # user's id all raise the same Mcp::ToolError.not_found.
    def find(association, id)
      records(association).find_by(id: record_id(id)) || raise(ToolError.not_found)
    end

    def write?
      oauth_scopes.include?("write")
    end

    private

    def record_id(value)
      value.to_s[/\A\d+\z/]
    end
  end
end
